//! TEXTAREA minimum length reflection and independent native editing.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><textarea id=area name=q maxlength=4>Seed</textarea><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://textarea-min-length.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn textarea_min_length_canonical_descriptor_default_and_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'minLength');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get minLength'||a.set.name!=='set minLength'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'minLength')||x.minLength!==-1)throw 'canonical minLength';var calls=0;x.minLength={valueOf:function(){calls++;return 3;}};if(calls!==1||x.minLength!==3||x.getAttributeNS(null,'minlength')!=='3'||x.maxLength!==4||x.value!=='Seed'||x.defaultValue!=='Seed')throw 'actual minimum reflection';");}
#[test]
fn textarea_min_length_content_prefix_missing_and_invalid(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.setAttribute('minlength',' +2tail');if(x.minLength!==2)throw 'HTML prefix';x.setAttribute('minlength','-1');if(x.minLength!==-1)throw 'invalid minimum';x.removeAttribute('minlength');if(x.minLength!==-1||x.maxLength!==4||x.value!=='Seed')throw 'missing minimum';");}
#[test]
fn textarea_min_length_negative_converted_long_is_real_dom_exception(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),calls=0;for(var bad of [-1,2147483648,4294967295]){try{x.minLength={valueOf:function(){calls++;return bad;}};throw 'missing negative refusal';}catch(e){if(!(e instanceof DOMException)||e.name!=='IndexSizeError')throw e;}}if(calls!==3||x.getAttribute('minlength')!==null||x.value!=='Seed')throw 'negative atomicity';x.minLength=4294967296;if(x.minLength!==0||x.getAttribute('minlength')!=='0')throw 'signed long wrap';");}

#[test]
fn textarea_min_length_getter_prefix_matrix_native_inert_exact_names_and_raw_backing(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','textarea');for(var target of [x,inert]){for(var pair of [['',-1],['-1',-1],['0',0],['-0',0],[' +2tail',2],['3.8',3],['0x20',0],['2147483647',2147483647],['2147483648',-1],['\u00a04',-1],['+4\ud800tail',4]]){target.setAttribute('minlength',pair[0]);if(target.minLength!==pair[1]||target.getAttributeNS(null,'minlength')!==pair[0])throw 'minimum prefix or exact raw record';}target.removeAttribute('minlength');target.setAttributeNS('urn:other','minlength','1');target.setAttributeNS(null,'MINLENGTH','1');if(target.minLength!==-1)throw 'namespace alias';target.minLength=2;if(target.minLength!==2||target.getAttributeNS('urn:other','minlength')!=='1'||target.getAttributeNS(null,'MINLENGTH')!=='1')throw 'canonical minimum namespace';}if(x.value!=='Seed'||x.defaultValue!=='Seed'||x.maxLength!==4)throw 'reflection changed editor';"#);}
#[test]
fn textarea_min_length_once_signed_long_conversion_reentrant_abrupt_and_type_errors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');for(var pair of [[undefined,0],[null,0],[NaN,0],[Infinity,0],[-Infinity,0],[-0,0],[-0.9,0],[1.9,1],[4294967299,3],[-4294967292,4]]){x.minLength=pair[0];if(x.minLength!==pair[1]||x.getAttributeNS(null,'minlength')!==String(pair[1]))throw 'minimum signed long';}var calls=0;x.minLength={valueOf:function(){calls++;x.minLength=2;return 5;}};if(calls!==1||x.minLength!==5||x.maxLength!==4)throw 'outer assignment or max alias';var marker={};try{x.minLength={valueOf:function(){calls++;x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(calls!==2||x.minLength!==5||x.getAttribute('data-side')!=='kept')throw 'abrupt state';for(var bad of [Symbol('bad'),BigInt(1)]){try{x.minLength=bad;throw 'missing type error';}catch(e){if(!(e instanceof TypeError))throw e;}}if(x.minLength!==5||x.value!=='Seed')throw 'type error mutation';");}
#[test]
fn textarea_min_length_actual_attribute_producers_observe_without_native_editor_changes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';x.minLength=5;var attribute=x.getAttributeNodeNS(null,'minlength'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['minlength']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('minlength',' +2tail');","x.setAttributeNS(null,'minlength',' +2tail');","attribute.value=' +2tail';","attribute.nodeValue=' +2tail';","attribute.textContent=' +2tail';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.minLength!==2||x.getAttributeNodeNS(null,'minlength')!==attribute||records.length!==1||records[0].target!==x||records[0].attributeName!=='minlength'||x.value!=='dirty'||x.defaultValue!=='Seed')throw 'actual minimum attribute mutation';");let c=&f.controls[&n];assert_eq!((c.max_length,c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(4,3,1,2,true));}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute('minlength');replacement.value='1';x.setAttributeNodeNS(replacement);if(x.minLength!==1||attribute.ownerElement!==null||replacement.ownerElement!==x||x.maxLength!==4)throw 'minimum Attr replacement';");}
#[test]
fn textarea_min_length_fragment_copy_detach_reconnect_and_typing_below_minimum(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.createElement('div');host.innerHTML='<textarea id=fresh maxlength=4 minlength=" +20tail"></textarea>';var x=host.firstChild;document.body.appendChild(host);if(x.minLength!==20||x.maxLength!==4)throw 'fragment min/max independent';x.value='dirty';var copy=x.cloneNode(true);copy.minLength=1;if(copy.minLength!==1||copy.value!=='dirty'||x.minLength!==20)throw 'dirty copied minimum';x.parentNode.removeChild(x);x.minLength=2147483647;document.getElementById('form').appendChild(x);if(x.minLength!==2147483647||x.value!=='dirty'||x.form!==document.getElementById('form'))throw 'reconnected minimum';x.value='';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("fresh")&&f.controls[n].owner.is_some()).unwrap();assert_eq!(f.controls[&n].max_length,4);f.controls.get_mut(&n).unwrap().insert("😀ZQmore");assert_eq!(f.controls[&n].value.text(),"😀ZQ");run(&mut d,&mut f,&mut p,"if(x.minLength!==2147483647||x.maxLength!==4||x.value!=='😀ZQ')throw 'minimum must not clamp typing';");}
#[test]
fn textarea_min_length_brand_before_conversion_saved_authority_and_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'minLength'),calls=0;for(var bad of [{},document,document.getElementById('neighbor'),Object.create(P)]){try{a.set.call(bad,{valueOf:function(){calls++;return 2;}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls||x.minLength!==-1)throw 'bad brand converted';Object.defineProperty(P,'minLength',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.minLength='override';a.set.call(x,3);if(x.minLength!=='author'||a.get.call(x)!==3||x.getAttribute('data-author')!=='override'||x.maxLength!==4)throw 'saved authority';delete P.minLength;if(x.minLength!==undefined)throw 'deleted hidden member';Object.defineProperty(P,'minLength',a);var C=HTMLTextAreaElement;delete window.HTMLTextAreaElement;if(!(x instanceof C)||a.get.call(x)!==3)throw 'saved roots';");}
#[test]
fn textarea_min_length_resource_refusal_preserves_dom_editor_and_recovers(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("textarea")};let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();let nodes=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let capture=|f:&Forms|{let c=&f.controls[&n];(c.max_length,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)};let before=capture(&f);let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_min_length_set(object,&Value::Number(2.0)).is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!((p.state.retained,p.state.dom_commits),state);assert_eq!(capture(&f),before);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.minLength=2;if(x.minLength!==2||x.maxLength!==4||x.value!=='dirty')throw 'fresh minimum recovery';");}}
#[test]
fn textarea_min_length_reads_allocate_nothing_saved_child_origin_precedes_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.minLength=3;var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'minLength'),calls=0;if(a.get.call(x)!==3)throw 'same origin getter';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("textarea")};let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=0;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_min_length_get(object),Ok(Value::Number(3.0))));p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.set_location(&crate::navigation::address("https://foreign-textarea-min-length.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("a.set.call(x,{valueOf:function(){calls++;return 1;}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://textarea-min-length.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.minLength!==3)throw 'origin converted';a.set.call(x,2);if(a.get.call(x)!==2||x.maxLength!==4)throw 'fresh origin recovery';");}
